set-variable.value:
@{
      var clients = JArray.Parse(System.Text.Encoding.UTF8.GetString(Convert.FromBase64String("{{pernova-client-ids-json}}")));
      var map = JObject.Parse(System.Text.Encoding.UTF8.GetString(Convert.FromBase64String("{{pernova-mcp-allowlist-json}}")));
      var client = (string)context.Variables["client-id"];
      if (!clients.Values<string>().Contains(client)) { return "[]"; }
      var tools = map[client] as JArray;
      return tools == null ? "[]" : tools.ToString(Newtonsoft.Json.Formatting.None);
    }

@{
      try {
        var body = context.Request.Body.As<JObject>(preserveContent: true);
        if ((string)body["jsonrpc"] != "2.0") { return false; }
        var method = (string)body["method"];
        if (method == "initialize" || method == "tools/list") { return true; }
        if (method != "tools/call") { return false; }
        var tool = (string)body["params"]?["name"];
        return tool != null && JArray.Parse((string)context.Variables["allowed-tools"]).Values<string>().Contains(tool);
      } catch { return false; }
    }

when.set-body:
@{
          var body = context.Response.Body.As<JObject>(preserveContent: true);
          var tools = body["result"]?["tools"] as JArray;
          if (tools != null) {
            var allowed = JArray.Parse((string)context.Variables["allowed-tools"]).Values<string>().ToArray();
            body["result"]["tools"] = new JArray(tools.Where(t => allowed.Contains((string)t["name"])));
          }
          return body.ToString(Newtonsoft.Json.Formatting.None);
        }
